(() => {
const $=id=>document.getElementById(id),params=new URLSearchParams(location.search),tabId=Number(params.get('tab')),pageURL=params.get('page')||'';
const rpc=async message=>{const response=await chrome.runtime.sendMessage(message);if(!response?.ok)throw Error(response?.error||'확장에 연결하지 못했습니다.');return response.value;};
let works=[],selectedId='',scopes=[],busy=false,readingItems=[],page=0,currentTarget='Korean';
const drafts=new Map(),pageSize=25,notice=message=>$('status').textContent=message;
const options=values=>Object.entries(values).map(([value,label])=>'<option value="'+value+'">'+label+'</option>').join('');
function fields(node){return Object.fromEntries([...node.querySelectorAll('[data-field]')].map(input=>[input.dataset.field,input.type==='checkbox'?input.checked:input.value]));}
function readEntry(node){const entry={...fields(node),id:node.dataset.id};entry.aliases=entry.aliases.split('\n').filter(line=>line.trim()).map(line=>{const split=line.indexOf('=');if(split<1)throw Error('별칭은 원문 = 번역명 형식으로 입력하세요.');return{source:line.slice(0,split).trim(),translation:line.slice(split+1).trim()};});return entry;}
function filterEntries(){
 const query=$('search').value.trim().toLocaleLowerCase(),kind=$('filter').value,all=[...$('entries').children];
 const matches=all.filter(node=>{const entry=fields(node);return(!kind||entry.kind===kind)&&(!query||['source','translation','reading','aliases'].some(key=>entry[key].toLocaleLowerCase().includes(query)));});
 page=Math.min(page,Math.max(0,Math.ceil(matches.length/pageSize)-1));const visible=new Set(matches.slice(page*pageSize,(page+1)*pageSize));for(const node of all)node.hidden=!visible.has(node);
 $('empty').hidden=matches.length>0;$('count').textContent=matches.length+' / '+all.length+'개';$('page-number').textContent=(page+1)+' / '+Math.max(1,Math.ceil(matches.length/pageSize));$('previous').disabled=page===0;$('next').disabled=(page+1)*pageSize>=matches.length;
}
function entryRow(entry={kind:'term'},open=false){
 const node=document.createElement('section');node.className='entry';node.dataset.id=entry.id||crypto.randomUUID();
 node.innerHTML='<div class="entry-line"><button class="expand" aria-label="상세 편집" aria-expanded="false">▸</button><select data-field="kind" aria-label="명칭 종류">'+options(MangaNames.kinds)+'</select><input data-field="source" aria-label="원문" placeholder="원문"><span class="arrow">→</span><input data-field="translation" aria-label="확정 번역" placeholder="확정 번역"></div><div class="entry-details" hidden><div class="general"><label>확인한 읽기·후리가나<input data-field="reading" placeholder="한자 표기와 다른 읽기 등을 기록"></label><label class="check"><input type="checkbox" data-field="matchReading">이 읽기 자체가 원문에 나와도 같은 번역 적용</label><p class="note">예: 戦乙女 → 발큐리아, 읽기 ヴァルキュリア. 읽기는 확인 후 등록하며, 매칭을 켜면 동일한 읽기에도 적용됩니다.</p><label>별칭·다른 원문 표기<textarea data-field="aliases" placeholder="원문 = 번역명 (한 줄에 하나)"></textarea></label></div><div class="personal"><div class="row"><label>원문 이름 부분<input data-field="givenSource"></label><label>이름 번역<input data-field="givenTranslation"></label><label>원문 성 부분<input data-field="familySource"></label><label>성 번역<input data-field="familyTranslation"></label></div><button class="suggest">성·이름 구분 제안</button><span class="note"> 제안은 확인한 뒤 저장하세요.</span></div><div class="honorific"><p class="note">등록된 인물명과 결합할 때 적용합니다. 번역을 비우면 호칭을 생략합니다.</p><div class="row"><label>원문 호칭 위치<select data-field="sourcePosition"><option value="suffix">이름 뒤 (ちゃん 등)</option><option value="prefix">이름 앞 (Mr. 등)</option></select></label><label class="check"><input type="checkbox" data-field="sourceGap">원문 이름과 한 칸 띄움</label><label>번역 호칭 위치<select data-field="position"><option value="suffix">이름 뒤</option><option value="prefix">이름 앞</option></select></label><label class="check"><input type="checkbox" data-field="gap">번역 이름과 한 칸 띄움</label></div></div><p class="entry-status note" role="status"></p><button class="remove danger">항목 삭제</button></div>';
 for(const input of node.querySelectorAll('[data-field]')){const key=input.dataset.field;if(input.type==='checkbox')input.checked=!!entry[key];else input.value=key==='aliases'?(entry.aliases||[]).map(alias=>alias.source+' = '+alias.translation).join('\n'):entry[key]||(key==='kind'?'person':['position','sourcePosition'].includes(key)?'suffix':'');}
 function kindChanged(){const kind=fields(node).kind;node.querySelector('.personal').hidden=kind!=='person';node.querySelector('.general').hidden=kind==='honorific';node.querySelector('.honorific').hidden=kind!=='honorific';node.querySelector('[data-field="translation"]').placeholder=kind==='honorific'?'번역 (비우면 생략)':'확정 번역';}
 function expand(value){node.querySelector('.entry-details').hidden=!value;node.querySelector('.expand').setAttribute('aria-expanded',String(value));node.querySelector('.expand').textContent=value?'▾':'▸';}
 node.querySelector('.expand').onclick=()=>{const opening=node.querySelector('.entry-details').hidden;for(const other of $('entries').children){other.querySelector('.entry-details').hidden=true;other.querySelector('.expand').setAttribute('aria-expanded','false');other.querySelector('.expand').textContent='▸';}expand(opening);};
 node.querySelector('[data-field="kind"]').onchange=kindChanged;
 node.querySelector('.remove').onclick=()=>{node.remove();filterEntries();notice('사전 저장을 누르면 삭제 내용이 반영됩니다.');};
 node.querySelector('.suggest').onclick=async()=>{const button=node.querySelector('.suggest'),status=node.querySelector('.entry-status'),before=fields(node);if(!before.source||!before.translation){status.textContent='원문 풀네임과 확정 번역명을 먼저 입력하세요.';return;}button.disabled=true;status.textContent='성·이름 구분을 제안하는 중…';try{const result=await rpc({type:'namesSuggest',source:before.source,translation:before.translation});if(!node.isConnected||JSON.stringify(fields(node))!==JSON.stringify(before)){status.textContent='입력 내용이 바뀌었습니다. 다시 요청하세요.';return;}for(const key of ['givenSource','givenTranslation','familySource','familyTranslation'])node.querySelector('[data-field="'+key+'"]').value=result[key]||'';status.textContent='제안을 확인한 뒤 저장하세요.';}catch(error){status.textContent=error.message;}finally{button.disabled=false;}};
 kindChanged();expand(open);$('entries').append(node);return node;
}
function collect(validate=true){const work={version:2,id:selectedId||(validate?crypto.randomUUID():''),title:$('title').value,target:currentTarget,revision:crypto.randomUUID(),scopes:[...scopes,...(pageURL&&$('bind').checked?[pageURL]:[])],entries:[...$('entries').children].map(readEntry)};return validate?MangaNames.validate(work):work;}
function show(work,target=currentTarget){selectedId=work?.id||'';currentTarget=work?.target||target;$('target').value=currentTarget;scopes=[...(work?.scopes||[])];$('title').value=work?.title||'';$('entries').replaceChildren();for(const entry of work?MangaNames.entries(work):MangaNames.defaultHonorifics(currentTarget).map(rule=>({...rule,kind:'honorific'})))entryRow(entry);$('scope-list').replaceChildren(...scopes.map(scope=>{const line=document.createElement('div');line.textContent=scope;return line;}));$('bind').checked=!!pageURL;page=0;$('search').value='';$('filter').value='';$('work').value=selectedId;filterEntries();notice('');}
function choices(){$('work').replaceChildren(new Option('새 사전',''),...works.map(work=>new Option(work.title+' · '+MangaNames.languages[work.target||'Korean'],work.id)));$('work').value=selectedId;}
async function protect(operation){if(busy)return;busy=true;$('save').disabled=true;$('work').disabled=true;$('target').disabled=true;try{await operation();}catch(error){notice(error.message);}finally{busy=false;$('save').disabled=false;$('work').disabled=false;$('target').disabled=false;}}
function rememberDraft(){drafts.set(selectedId||'new:'+currentTarget,collect(false));}
for(const [value,label]of Object.entries(MangaNames.kinds))$('filter').add(new Option(label,value));
$('search').oninput=$('filter').onchange=()=>{page=0;filterEntries();};$('previous').onclick=()=>{page--;filterEntries();};$('next').onclick=()=>{page++;filterEntries();};
$('add').onclick=()=>{const kind=$('filter').value||'term';$('search').value='';const node=entryRow({kind},true);page=Math.floor(([...$('entries').children].filter(entry=>!$('filter').value||fields(entry).kind===kind).length-1)/pageSize);filterEntries();node.querySelector('[data-field="source"]').focus();};
$('work').onchange=()=>protect(async()=>{const next=$('work').value;rememberDraft();show(drafts.get(next||'new:'+currentTarget)||works.find(work=>work.id===next));});
$('target').onchange=()=>protect(async()=>{const target=$('target').value;rememberDraft();const current=collect(false),same=works.find(work=>(work.target||'Korean')===target&&((current.scopes.length&&work.scopes?.some(scope=>current.scopes.map(MangaNames.identity).includes(scope)))||(!current.scopes.length&&work.title===current.title)));show(drafts.get(same?.id||'new:'+target)||same||{version:2,title:current.title,target,scopes:current.scopes,entries:[]},target);notice('번역 언어별로 사전이 분리됩니다. 다른 언어의 표기는 유지됩니다.');});
$('save').onclick=()=>protect(async()=>{const work=collect(),saved=await rpc({type:'namesSave',work});drafts.delete(selectedId||'new:'+currentTarget);works=saved.works;selectedId=work.id;choices();show(work);notice('사전을 저장했습니다. 새 번역에 적용됩니다. 기존 결과는 패널의 명칭 통일을 누르세요.');});
$('export').onclick=()=>protect(async()=>{const work=collect(),url=URL.createObjectURL(new Blob([JSON.stringify({version:2,work},null,2)],{type:'application/json'})),link=document.createElement('a');link.href=url;link.download=work.title.replace(/[\\/:*?"<>|]/g,'_')+'-'+work.target+'-명칭사전.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
$('import').onclick=()=>$('import-file').click();$('import-file').onchange=()=>protect(async()=>{const file=$('import-file').files[0];if(!file)return;if(file.size>262144)throw Error('사전 파일이 너무 큽니다.');const data=JSON.parse(await file.text()),work=MangaNames.validate(data.work||data);rememberDraft();show({...work,id:'',scopes:[]});notice('가져온 명칭을 확인하고 현재 작품에 저장하세요.');$('import-file').value='';});
$('current-page').textContent=pageURL?'현재 만화: '+pageURL:'만화 패널의 명칭 사전 버튼으로 열면 현재 작품에 연결할 수 있습니다.';
(async()=>{const context=await rpc({type:'namesContext',pageURL});works=context.works||[];currentTarget=context.target||'Korean';selectedId=context.work?.id||'';choices();show(context.work);if(Number.isInteger(tabId)&&tabId>0){try{const saved=await rpc({type:'control',tabId,action:'nameRegions'});readingItems=saved?.regions||[];$('reading-tools').hidden=!readingItems.length;for(const [index,item]of readingItems.entries())$('reading-region').add(new Option(item.page+'p · '+item.text.slice(0,50),String(index)));}catch{}}})().catch(error=>notice(error.message));
$('reading-view').onclick=()=>protect(async()=>{const item=readingItems[Number($('reading-region').value)];if(!item)return;const response=await rpc({type:'nameReading',id:item.id,region:item.region,preview:true});$('reading-preview').src=response.preview;$('reading-status').textContent='원문과 작은 읽기 표기를 확인하세요. 확정 번역은 자동으로 변경되지 않습니다.';});
$('reading-run').onclick=()=>protect(async()=>{const item=readingItems[Number($('reading-region').value)];if(!item)return;$('reading-status').textContent='후리가나 영역을 분리해 읽는 중…';const response=await rpc({type:'nameReading',id:item.id,region:item.region});$('reading-preview').src=response.preview;$('reading-result').textContent=(response.candidates||[]).map(candidate=>candidate.text).join('\n')||'후리가나 읽기를 찾지 못했습니다.';$('reading-status').textContent='원본과 비교해 확인한 읽기를 항목에 등록하세요. 제안만으로 확정 표기를 바꾸지 않습니다.';});
})();
